import{_ as a,C as s,o as n,c as l,a2 as o,E as r}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Product Form Layout","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-form-layout.md","filePath":"catalog/product-form-layout.md","lastUpdated":1789411447000}'),i={name:"catalog/product-form-layout.md"};function g(d,t,u,h,c,p){const e=s("ImagePopup");return n(),l("div",null,[t[0]||(t[0]=o('<h1 id="product-form-layout" tabindex="-1">Product Form Layout <a class="header-anchor" href="#product-form-layout" aria-label="Permalink to &quot;Product Form Layout&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>The product form sellers fill in can be shown as guided steps or as a classic page with two columns. You set the default for every product, and you can give each attribute family its own layout and step order. This only changes the seller&#39;s form. The admin product form stays the same.</p><h2 id="set-the-default-for-all-families" tabindex="-1">Set the default for all families <a class="header-anchor" href="#set-the-default-for-all-families" aria-label="Permalink to &quot;Set the default for all families&quot;">​</a></h2><p>The defaults live in <strong>Configure &gt;&gt; Marketplace &gt;&gt; Products</strong>, in the <strong>Product Form</strong> section: <strong>Enable Stepped Product Form</strong>, <strong>Stepped Form Navigation</strong> and <strong>Show Progress Bar</strong>. See <a href="./../configuration/products#product-form">Products settings</a>.</p><p>Turning off <strong>Enable Stepped Product Form</strong> also gives sellers a simpler, one-page <strong>List Your Product</strong> screen instead of the guided one. Family layouts don&#39;t change that screen.</p><h2 id="the-product-form-list" tabindex="-1">The Product Form list <a class="header-anchor" href="#the-product-form-list" aria-label="Permalink to &quot;The Product Form list&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Product Form</strong>. The list has one row for each attribute family.</p>',8)),r(e,{src:"/images/product-form-layout/form-layout-list.png",alt:"The Product Form Layout list of attribute families"}),t[1]||(t[1]=o('<table tabindex="0"><thead><tr><th>Column</th><th>Values</th></tr></thead><tbody><tr><td><strong>Attribute Family</strong></td><td>The family&#39;s name</td></tr><tr><td><strong>Layout</strong></td><td><strong>Inherit (Global)</strong>, <strong>Stepped</strong> or <strong>Two Column</strong></td></tr><tr><td><strong>Navigation</strong></td><td><strong>Inherit (Global)</strong>, <strong>Horizontal Tabs</strong> or <strong>Vertical Rail</strong></td></tr></tbody></table><p><strong>Inherit (Global)</strong> follows the default you set on the Configure page.</p><p>To change several families at once, tick them, click <strong>Select Action</strong>, and use <strong>Update Layout</strong> or <strong>Update Navigation</strong>.</p><h2 id="configure-one-family" tabindex="-1">Configure one family <a class="header-anchor" href="#configure-one-family" aria-label="Permalink to &quot;Configure one family&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Product Form</strong>.</li><li>Click <strong>Configure</strong> on the family&#39;s row.</li><li>In <strong>General</strong>, choose the <strong>Form Layout</strong>.</li><li>If the layout is stepped, choose the <strong>Step Navigation</strong>.</li><li>In <strong>Step Order</strong>, drag the steps into the order sellers should see them.</li><li>Click <strong>Save</strong>.</li></ol>',5)),r(e,{src:"/images/product-form-layout/configure-family.png",alt:"Configuring the step order and layout for one attribute family"}),t[2]||(t[2]=o('<ul><li><strong>Step Order</strong> lists the family&#39;s attribute groups. <strong>Media</strong>, the step for the product type, and <strong>Organization</strong> always come last.</li><li><strong>Step Order</strong> and <strong>Step Navigation</strong> only apply to the stepped form, so they are turned off when you choose <strong>Two Column</strong>, or <strong>Inherit (Global)</strong> while the global stepped form is off.</li></ul><h2 id="what-sellers-see" tabindex="-1">What sellers see <a class="header-anchor" href="#what-sellers-see" aria-label="Permalink to &quot;What sellers see&quot;">​</a></h2><ul><li><strong>Stepped</strong> — one step at a time, with the steps in a scrolling row of tabs (<strong>Horizontal Tabs</strong>) or, on wide screens, in a list down the side (<strong>Vertical Rail</strong>; smaller screens still show tabs). Sellers move with <strong>Previous</strong> and <strong>Next</strong>, and a step with a mistake is marked.</li><li><strong>Two Column</strong> — the whole form on one page, in two columns.</li></ul><p>See <a href="./product-management">Product Management</a> for how sellers fill in the form.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>To give another admin access, tick <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Product Form Layout</strong> and <strong>Edit</strong> in their role.</p>',6))])}const y=a(i,[["render",g]]);export{f as __pageData,y as default};
